import React, { useState } from "react";
import { useGetCaptcha } from "../../../hooks/ims/useCaptcha";
import {
  Modal,
  Button,
  Form,
  Container,
  Row,
  Col,
} from "@themesberg/react-bootstrap";
import { LoadingCircle } from "../../components/icons";
import { useCgpaUpdate } from "../../../hooks/ims/useCgpaUpdate";
import toast from "react-hot-toast";

export default function CGPAUpdateModal() {
  const [enabled, setEnabled] = useState(false);
  const { data: captchaUrl, isLoading: captchaLoading } = useGetCaptcha({
    enabled: enabled,
  });
  const { mutateAsync, isLoading } = useCgpaUpdate();
  const [show, setShow] = useState(false);
  const [password, setPassword] = useState("");
  const [captchaValue, setCaptchaValue] = useState("");

  const handleClose = () => {
    setShow(false);
    setEnabled(false);
    setPassword("");
    setCaptchaValue("");
  };

  const handleShow = () => {
    setShow(true);
    setEnabled(true);
  };

  async function handleSubmit(e) {
    e.preventDefault();
    if (captchaUrl === undefined || isLoading) {
      return;
    }

    const data = await mutateAsync({
      password: password,
      captcha: captchaValue,
    });

    if (data.success) {
      toast.success("Cgpa updated successfully");
      window.location.reload();
    }
  }

  return (
    <>
      <Button
        style={{
          backgroundColor: "#EE3444",
          border: "none",
          margin: "1rem",
          padding: "1rem",
          color: "white",
          cursor: "pointer",
        }}
        variant="outline-primary"
        onClick={handleShow}
      >
        Update CGPA
      </Button>

      <Modal show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>Update CGPA</Modal.Title>
        </Modal.Header>

        <Form onSubmit={handleSubmit}>
          <Modal.Body>
            <p className="text-muted">
              Please verify your identity to update your CGPA information.
            </p>

            <Container className="py-3">
              <Form.Group className="mb-3">
                <Form.Label>IMS Password</Form.Label>
                <Form.Control
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                />
              </Form.Group>

              <Form.Group>
                <Form.Label>Enter Captcha</Form.Label>
                <Row>
                  <Col>
                    {captchaLoading ? (
                      <LoadingCircle />
                    ) : (
                      <img
                        src={captchaUrl}
                        alt="captha"
                        style={{ width: "100%" }}
                      />
                    )}
                  </Col>
                  <Col>
                    <Form.Control
                      type="text"
                      value={captchaValue}
                      onChange={(e) => setCaptchaValue(e.target.value)}
                      required
                    />
                  </Col>
                </Row>
              </Form.Group>
            </Container>
          </Modal.Body>

          <Modal.Footer>
            <Button variant="primary" type="submit" disabled={isLoading}>
              {isLoading ? <LoadingCircle /> : "Continue"}
            </Button>
          </Modal.Footer>
        </Form>
      </Modal>
    </>
  );
}
