import { useMutation, useQueryClient } from "react-query";
import { securedAxiosInstance } from "../../axiosConfig";
import toast from "react-hot-toast";

async function updateCgpa(data) {
  const res = await securedAxiosInstance.post("/students/cgpa-update", data, {
    withCredentials: true,
  });

  if (!res.data.success) {
    throw new Error(res.data.message);
  }

  return res.data;
}

export function useCgpaUpdate() {
  const queryClient = useQueryClient();

  const { mutate, mutateAsync, isLoading } = useMutation({
    mutationFn: updateCgpa,
    mutationKey: "cgpa-update",
    onError: (error) => {
      queryClient.invalidateQueries("captcha");
      toast.error(error.message);
    },
  });

  return { mutate, mutateAsync, isLoading };
}
